mapper.select:
SELECT 
FROM trip_track_chunks
WHERE trip_id = #{tripId} AND user_id = #{userId} AND local_date = #{localDate}
ORDER BY started_at, id
LIMIT #{limit}

mapper.delete:
DELETE FROM trip_track_chunks
WHERE id IN (
    SELECT c.id
    FROM trip_track_chunks c
    JOIN trips t ON t.id = c.trip_id
    WHERE t.end_date <= #{lastTripEndDate}
    ORDER BY c.local_date, c.id
    LIMIT #{limit}
)

mapper.select:
SELECT id, trip_id, user_id, local_date, day_number, line_segments, bbox, distance_m, flight_distance_m,
       moving_seconds, elevation_gain_m, elevation_loss_m, point_count, province_codes, first_at, last_at,
       created_at, updated_at, data_version
FROM trip_track_days
WHERE trip_id = #{tripId}
  AND user_id IN
  #{userId}
  AND day_number = #{dayNumber}
ORDER BY user_id, local_date
LIMIT #{limit}

SELECT DISTINCT user_id
FROM trip_track_days
WHERE trip_id = #{tripId}
ORDER BY user_id
LIMIT #{limit}

SELECT id, trip_id, user_id, local_date, kind, activity_id, place_id, name, latitude, longitude,
       arrived_at, departed_at, status, created_activity_id, created_at, updated_at, data_version
FROM trip_track_visits
WHERE trip_id = #{tripId}
  AND user_id IN
  #{userId}

      AND local_date IN
      #{localDate}

ORDER BY user_id, local_date, arrived_at, id
LIMIT #{limit}

SELECT user_id, SUM(distance_m) AS distance_m
FROM trip_track_days
WHERE trip_id = #{tripId}
GROUP BY user_id
ORDER BY user_id
LIMIT #{limit}

SELECT user_id, MAX(created_at) AS last_at
FROM user_checkins
WHERE trip_id = #{tripId}
  AND is_removed = FALSE
  AND user_id IN
  #{userId}
  AND created_at >= #{fromUtc}
  AND created_at < #{toUtc}
GROUP BY user_id
ORDER BY user_id
LIMIT #{limit}

SELECT 
FROM trip_track_settings
WHERE trip_id = #{tripId} AND user_id = #{userId}

SELECT 
FROM trip_track_settings
WHERE trip_id = #{tripId}
ORDER BY user_id
LIMIT #{limit}

mapper.update:
UPDATE trip_track_settings
SET visibility = #{settings.visibility},
    trim_day_ends = #{settings.trimDayEnds},
    default_accuracy = #{settings.defaultAccuracy},
    auto_enabled = #{settings.autoEnabled},
    updated_at = NOW(),
    data_version = data_version + 1
WHERE id = #{settings.id}
  AND user_id = #{settings.userId}
  AND data_version = #{expectedVersion}

mapper.select:
SELECT id, user_id, name, latitude, longitude, radius_m, created_at, updated_at, data_version
FROM user_privacy_zones
WHERE user_id = #{userId}
ORDER BY created_at, id
LIMIT #{limit}

SELECT id, user_id, name, latitude, longitude, radius_m, created_at, updated_at, data_version
FROM user_privacy_zones
WHERE user_id IN
#{userId}
ORDER BY user_id, created_at, id
LIMIT #{limit}

mapper.insert:
INSERT INTO user_privacy_zones (
    id, user_id, name, latitude, longitude, radius_m, created_at, updated_at, data_version
) VALUES (
    #{id}, #{userId}, #{name}, #{latitude}, #{longitude}, #{radiusM}, NOW(), NOW(), 1
)

mapper.update:
UPDATE user_privacy_zones
SET name = #{zone.name},
    latitude = #{zone.latitude},
    longitude = #{zone.longitude},
    radius_m = #{zone.radiusM},
    updated_at = NOW(),
    data_version = data_version + 1
WHERE id = #{zone.id}
  AND user_id = #{zone.userId}
  AND data_version = #{expectedVersion}
